mapper.select:
select id as videoId, cover_url as coverUrl, play_url as playUrl, like_count as likeCount, status
from video
where user_id = #{userId}

select v.id as videoId, v.user_id as userId, u.nickname as nickName, u.avatar_url as avatarUrl, v.category_id as categoryId, v.title, v.play_url as playUrl, v.cover_url as coverUrl, v.duration, v.like_count as likeCount, if(vl.video_id is not null, true, false) as isLiked, v.comment_count as commentCount, v.share_count as shareCount, v.created_time as createdTime
from video v
left join user_high u on v.user_id = u.id
left join video_like vl on v.id = vl.video_id and vl.user_id = #{userId}

    v.id = #{videoId}

select v.id as videoId, v.user_id as userId, u.nickname as nickName,  v.title, v.play_url as playUrl, v.cover_url as coverUrl, v.duration, v.like_count as likeCount, if(vl.video_id is not null, true, false) as isLiked, v.created_time as createdTime
from video v
left join user_high u on v.user_id = u.id
left join video_like vl on vl.video_id = v.id and vl.user_id = #{userId}


        and v.category_id = #{category}


        and v.title like CONCAT('%', #{keyword}, '%')


        and v.id < #{lastId}


order by v.id desc
limit #{size}
